<template><div><h1>Projects</h1><ProjectForm :project="editProject" @save="save"/><input v-model="search" placeholder="Search projects"/><div class="card-grid"><ProjectCard v-for="p in filtered" :key="p.id" :project="p"/></div></div></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue';import ProjectForm from '../components/ProjectForm.vue';import ProjectCard from '../components/ProjectCard.vue';import { projectService } from '../db/projectService';const projects=ref<any[]>([]);const search=ref('');const editProject=ref<any>({name:'',status:'Idea',priority:'Normal',progress:0});const load=async()=>{projects.value=await projectService.all();};onMounted(load);const save=async(p:any)=>{if(p.id) await projectService.update(p.id,p); else await projectService.create(p); editProject.value={name:'',status:'Idea',priority:'Normal',progress:0}; await load();};const filtered=computed(()=>projects.value.filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase())));</script>
